      "activity_1": {
        "name": "Idiom Detective",
        "type": "Receptivity",
        "duration": "15 Minutes",
        "procedure": [
          "Teacher presents 10 idioms on the board with their definitions (translated to L1/L2).",
          "Students match the idioms to the definitions.",
          "Students identify which ones match their own cultural equivalents and which are unique to English."
        ],
        "materials_needed": "Worksheet with 10 idioms and definition pairs."
      },
      "activity_2": {
        "name": "Idiom Bridge Game",
        "type": "Memory/Application",
        "duration": "20 Minutes",
        "procedure": [
          "Students are given incomplete sentences requiring an idiom or adjective.",
          "The teacher plays the role of an interviewer asking for clarification on sentence structures.",
          "Students work in pairs to fill in the blanks, finding out when and where the idiomatic phrase can be used effectively.",
          "Class discussion: Why is the idiom used here?"
        ]
      },
      "activity_3": {
        "name": "Idiom Storytelling Challenge",
        "type": "Creative Expression",
        "duration": "35 Minutes",
        "procedure": [
          "Students are divided into groups of 4.",
          "Each group writes a short story (150-200 words) incorporating at least 5 distinct idioms taught.",
          "They must incorporate idioms such as 'hit the ropes', 'daydream', 'light as a feather', etc.",
          "Groups present their story, and peers identify anyone who misspelled/misspoke the idioms."
