      },
      "activity_4": {
        "name": "Exit Ticket",
        "type": "Assessment",
        "duration": "10 Minutes",
        "procedure": [
          "Each student writes down one new idiom they learned today.",
          "They must construct a sentence that uses the idiom in a context other than the classroom lesson.",
          "Submit to teacher for correction and feedback."
        ]
      }
