      ]
    },
    "additional_course_material": {
      "worksheets": [
        "Idiom Matching Chart",
        "Idiom Definition Cards",
        "Short Story Template"
      ],
      "homework": "Compile a personal 'Idiom Notebook' with 10 new idioms collected from movies, news articles, or books, with context examples."
    }
  }
}

{
