    "teaching_objectives": [
      {
        "type": "Cognitive",
        "statement": "Students will be able to define acids and bases based on their properties and behavior in aqueous solutions."
      },
      {
        "type": "Cognitive",
        "statement": "Students will understand the logarithmic scale of the pH scale and how to distinguish between acidic, neutral, and alkaline solutions."
      },
      {
        "type": "Psychomotor",
        "statement": "Students will be able to correctly use pH paper or indicators to test various household substances."
      },
      {
        "type": "Affective",
        "statement": "Students will appreciate the importance of chemical safety and the environmental relevance of pH levels."
      }
    ],
    "key_points": [
      "Definitions: Acids (produce H+ ions), Bases (produce OH- ions) according to Arrhenius definition.",
      "The pH Scale: 0-14, where <7 is acidic, 7 is neutral, and >7 is alkaline/basic.",
      "Indicators: Litmus paper and universal indicator as primary tools for identification.",
      "Physical properties: Sour taste (acids), slippery feel (bases), reaction with metal (acids).",
      "Application in real life: Stomach acid, soap making, blood circulation, environmental acidity."
